import { icon } from './icons.js';
import { BRAND_LOGOS, brandLogo } from './assets/brands/manifest.js';

const $ = (s, scope=document) => scope.querySelector(s);
const $$ = (s, scope=document) => [...scope.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = (v, digits=1) => typeof v === 'number' && Number.isFinite(v) ? v.toLocaleString(undefined,{maximumFractionDigits:digits}) : '—';
const rate = v => v == null ? '—' : num(v*8/1e6, 2);
const pct = v => v == null ? '—' : `${num(v)}%`;
const bytes = v => v == null ? '—' : `${num(v/1073741824,1)} GB`;
const uptime = v => v == null ? '—' : v >= 86400 ? `${Math.floor(v/86400)}d ${Math.floor(v%86400/3600)}h` : `${Math.floor(v/3600)}h ${Math.floor(v%3600/60)}m`;
const date = v => {if(v==null||v==='')return '—';const d=new Date(typeof v === 'number' ? v*1000 : v);return Number.isNaN(+d)?'—':d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});};
const PROVIDERS = {
  homeassistant:{name:'Home Assistant',icon:'home',color:'',detail:'Automations & smart devices',host:'http://homeassistant.local:8123'},
  samsung:{name:'Samsung TV',icon:'tv',color:'',detail:'Direct network pairing · optional Home Assistant',host:'192.168.1.50'},
  androidtv:{name:'Google / Android TV',icon:'tv',color:'green',detail:'Direct network pairing · optional Home Assistant',host:'192.168.1.50'},
  appletv:{name:'Apple TV',icon:'tv',color:'purple',detail:'Direct network pairing · optional Home Assistant',host:'192.168.1.50'},
  hisense:{name:'Hisense TV',icon:'tv',color:'green',detail:'Direct network pairing · optional Home Assistant',host:'192.168.1.50'},
  roku:{name:'Roku TV',icon:'tv',color:'purple',detail:'Direct Roku ECP on the local network',host:'192.168.1.50'},
  webos:{name:'LG webOS TV',icon:'tv',color:'red',detail:'Direct approval on the TV',host:'192.168.1.50'},
  hikvision:{name:'Hikvision',icon:'camera',color:'red',detail:'Authorized ISAPI cameras',host:'http://192.168.1.100'},
  server:{name:'Raspberry Pi / Server',icon:'server',color:'green',detail:'Prometheus node_exporter',host:'http://raspberrypi.local:9100'},
  ollama:{name:'Ollama',icon:'sparkles',color:'purple',detail:'Local AI model server',host:'http://127.0.0.1:11434'}
};
const TV_TYPES=['samsung','androidtv','appletv','hisense','roku','webos'];
const TV_PLATFORMS={samsung:'Samsung · modern network remote',androidtv:'Google / Android TV · including supported Hisense',appletv:'Apple TV · supported tvOS pairing',roku:'Roku / Roku TV',webos:'LG webOS'};
const directTV=i=>i.connectionMode==='direct';
const insecureTV=p=>['samsung','roku','webos'].includes(p);
const NAV=[['overview','grid','Overview'],['devices','devices','Devices'],['network','activity','Network'],['cameras','camera','Cameras'],['automations','automations','Automations'],['assistant','sparkles','AI assistant']];
const state={status:{},overview:{host:{},network:{history:[]},devices:[],integrations:[],events:[],actions:[]},settings:{},page:location.hash.slice(1)||'overview',tab:'integrations',deviceFilter:'all',deviceSearch:'',entities:[],entityErrors:[],servers:[],serverErrors:[],entityFilter:'all',cameraUrls:{},messages:[],chatBusy:false,scanBusy:false,sidebarOpen:false,refreshing:false,graphRange:5,online:true,modal:null};
if(![...NAV.map(n=>n[0]),'settings'].includes(state.page))state.page='overview';

async function api(path, body, method){
  const response=await fetch('/api'+path,{method:method||(body?'POST':'GET'),credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...(body&&state.status.csrfToken?{'X-CSRF-Token':state.status.csrfToken}:{})},body:body?JSON.stringify(body):undefined});
  const data=await response.json().catch(()=>({message:'The server returned an invalid response.'}));
  if(!response.ok){if(response.status===401 && !path.startsWith('/auth/')){clearPrivateState();render();}throw new Error(data.message||'The request could not be completed.');}
  return data;
}
function toast(message,error=false){const root=$('#toast-root');root.innerHTML=`<div class="toast ${error?'error':''}" role="status">${esc(message)}</div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>root.innerHTML='',6500);}
function clearPrivateState(){for(const url of Object.values(state.cameraUrls||{}))URL.revokeObjectURL(url);state.cameraUrls={};state.status={...state.status,authenticated:false,csrfToken:undefined,user:undefined};state.overview={host:{},network:{history:[]},devices:[],integrations:[],events:[],actions:[]};state.settings={};state.messages=[];state.entities=[];state.entityErrors=[];state.servers=[];state.serverErrors=[];state.serversLive=false;if(state.modal)closeModal();}
async function refresh(renderPage=true){
  if(!state.status.authenticated)return;
  try{state.overview=await api('/overview');state.online=true;if(renderPage&&!state.modal&&!state.sidebarOpen&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&['overview','network','devices','cameras'].includes(state.page))render();else updateNavBadge();}
  catch(e){state.online=false;if(renderPage)toast(e.message,true);}
}
function updateNavBadge(){const n=$('[data-approval-count]');if(n){const count=pending().length;n.textContent=count;n.hidden=!count;}}
function pending(){return (state.overview.actions||[]).filter(a=>a.status==='pending'&&a.expiresAt>Date.now()/1000);}
function integration(type){return(state.overview.integrations||[]).find(i=>i.type===type);}
function logo(type){const p=PROVIDERS[type]||PROVIDERS.server;return `<span class="integration-logo ${p.color}">${icon(p.icon)}</span>`;}
function button(text,action,ic='',kind='secondary',extra=''){return `<button class="btn ${kind}" data-action="${action}" ${extra}>${ic?icon(ic):''}${text}</button>`;}
function pill(text,connected=false){return `<span class="pill ${connected?'':'muted'}"><i class="dot ${connected?'':'gray'}"></i>${esc(text)}</span>`;}
function networkIdentityBadge(){
  const identity=state.overview.networkIdentity||{},isp=identity.isp||{},router=identity.router||{};
  const routerArtwork=brandLogo(router.id,'router');
  const ispArtwork=brandLogo(isp.id,'isp');
  const artwork=routerArtwork||ispArtwork,brandLabel=routerArtwork?(router.name||artwork.name):(isp.name||'Network');
  const providerMark=routerArtwork&&ispArtwork?`<img class="brand-logo-image" src="${esc(ispArtwork.darkLogo||ispArtwork.monoLogo||ispArtwork.logo)}" alt="${esc(isp.name||ispArtwork.name)} — internet provider" width="13" height="13">`:'';
  return `<button class="network-identity-badge" data-action="network-identity" aria-label="Internet provider and router settings" title="Detected public internet exit; VPN routing can differ from your retail ISP. Click to customize."><span class="router-brand-art ${artwork?'has-logo':''}">${artwork?`<img class="brand-logo-image" src="${esc(artwork.darkLogo||artwork.monoLogo||artwork.logo)}" alt="${esc(brandLabel)} — ${routerArtwork?'router company':'internet provider'}" width="64" height="26"><span class="brand-logo-fallback" hidden>${icon(routerArtwork?'router':'globe')}</span>`:icon('router')}<small>${esc(routerArtwork?(router.name||'ROUTER'):ispArtwork?'ISP / EXIT':router.name||'NETWORK')}</small></span><span class="identity-divider"></span><span class="provider-identity"><small>INTERNET PROVIDER</small><strong>${providerMark}${esc(isp.name||'Identify your ISP')}</strong><span><i class="dot ${isp.name?'':'gray'}"></i>${isp.source==='manual'?'Manual provider':isp.name?(isp.status==='unavailable'?'Auto · check unavailable':'Auto · detected internet exit'):'Automatic · not checked yet'}</span></span>${icon('chevron')}</button>`;
}
function shell(content){
  const pageName=NAV.find(n=>n[0]===state.page)?.[2]||'Settings';
  const now=new Date();
  return `<aside class="sidebar ${state.sidebarOpen?'open':''}" id="sidebar">
    <div class="brand"><div class="brand-mark">${icon('home')}</div><span>homebase<span style="color:var(--mint)">.</span></span></div>
    <button class="home-switch" data-action="workspace" aria-haspopup="dialog" aria-label="Workspace menu">${icon('home')}<div><strong>${esc(state.settings.workspaceName||'My home')}</strong><small>Local workspace</small></div>${icon('down')}</button>
    <p class="nav-label">COMMAND CENTRE</p>
    <nav class="nav" aria-label="Main navigation">${NAV.map(([id,ic,label])=>`<button class="nav-item ${state.page===id?'active':''}" data-nav="${id}" title="${label}" ${state.page===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='devices'&&state.overview.devices.length?`<span class="nav-count">${state.overview.devices.length}</span>`:''}</button>`).join('')}</nav>
    <div class="sidebar-bottom"><nav class="nav nav-section" aria-label="Workspace settings"><button class="nav-item ${state.page==='settings'?'active':''}" data-nav="settings" title="Settings">${icon('settings')}<span>Settings</span></button><button class="nav-item" data-action="help" title="Setup guide">${icon('info')}<span>Help & getting started</span></button></nav><div class="side-status">${icon('shield')}<div><strong>Your home stays yours.</strong><span>Private by design. Local by default.</span></div></div><div class="sidebar-version"><span>HomeBase OS</span><span>v${esc(state.status.version||'1.0.0')}</span></div></div>
  </aside><div class="mobile-backdrop" data-action="menu"></div>
  <div class="workspace"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumb">${icon('home')}<span>${esc(state.settings.workspaceName||'My home')}</span><span>/</span><strong>${pageName}</strong></div><div class="top-right"><button class="search-trigger" data-action="search">${icon('search')}<span>Search anything…</span><kbd>⌘ K</kbd></button><div class="top-time">${now.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}<small>${now.toLocaleDateString([],{weekday:'short',day:'numeric',month:'short'})}</small></div><button class="icon-button" data-action="activity" aria-label="View activity and pending approvals">${icon('bell')}<span class="notification-count" data-approval-count ${pending().length?'':'hidden'}>${pending().length}</span></button><button class="avatar" data-action="account" aria-label="Account settings">${state.status.authenticated?esc(state.status.user?.slice(0,2).toUpperCase()):icon('lock')}</button></div></header>
  <main class="content" id="main">${!state.online?`<div class="note connectivity-banner">${icon('info')}Connection to the local service was lost. Reconnecting…</div>`:''}${content}<footer class="footer"><div class="footer-left"><span><i class="dot"></i> ${state.status.authenticated?'Local service connected':'Local service ready'}</span><span>${icon('shield')} Encrypted at rest</span><span>${icon('globe')} No cloud required</span></div><span>${icon('refresh',state.refreshing?'refresh-mark':'')} ${state.status.authenticated?'Live telemetry · refreshes every 3s':'Your private command centre'}</span></footer></main></div>`;
}
function heading(title,subtitle,actions='',eyebrow='HOME, CONNECTED'){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function authBanner(){return state.status.authenticated?'':`<div class="setup-banner">${icon('shield')}<div><strong>${state.status.setupRequired?'Make yourself at home.':'Welcome back to your home.'}</strong><p>${state.status.setupRequired?'Create your private account to bring your command centre online.':'Sign in to see your devices and live home telemetry.'}</p></div>${button(state.status.setupRequired?'Secure my home':'Sign in','auth','arrow','')}</div>`;}
function orb(){return `<div class="orb-scene" aria-hidden="true"><div class="stars"></div><div class="orbit-ring"></div><div class="orb"></div></div>`;}
function spark(key,color){const points=(state.overview.network.history||[]).filter(p=>p[key]!=null).slice(-25);if(points.length<2)return '';const max=Math.max(...points.map(p=>p[key]),1);return `<svg class="stat-spark" viewBox="0 0 80 28" aria-hidden="true"><path d="${points.map((p,i)=>`${i?'L':'M'}${i*80/(points.length-1)},${26-p[key]/max*23}`).join(' ')}" fill="none" stroke="${color}" stroke-width="1.5"/></svg>`;}
function stats(){const {network:n,devices:d}=state.overview;const auth=state.status.authenticated;const online=d.filter(x=>x.online).length;return `<div class="stats-grid">
  <div class="card stat"><div class="stat-top">Network devices<span class="stat-icon">${icon('devices')}</span></div><div class="stat-value">${auth?d.length:'—'}<span>devices</span></div><div class="stat-bottom"><i class="dot ${online?'':'gray'}"></i>${auth?`${online} seen · ${d.filter(x=>x.online==null).length} unverified`:'Waiting for secure setup'}</div></div>
  <div class="card stat traffic-stat"><div class="stat-top">Live receive traffic<span class="stat-icon blue">${icon('download')}</span></div><div class="stat-value">${rate(n.rxBps)}<span>Mbps</span></div><div class="stat-bottom">${icon('activity')}Host interface usage</div><div class="traffic-spark" aria-label="Recent receive traffic">${spark('rxBps','#75c8f1')}</div></div>
  <div class="card stat"><div class="stat-top">Network latency<span class="stat-icon purple">${icon('activity')}</span></div><div class="stat-value">${num(n.latencyMs)}<span>ms</span></div><div class="stat-bottom"><i class="dot ${n.latencyMs==null?'gray':'purple'}"></i>${n.discoveryStarted?'Gateway round-trip time':'Available after a network scan'}</div>${spark('latencyMs','#ad9cf3')}</div>
  <button class="card stat security-stat" data-action="security-details" aria-label="View application security details"><div class="stat-top">App security<span class="stat-icon">${icon('shield')}</span></div><div class="stat-value" style="font-size:23px;line-height:1.45">${auth?(state.settings.security?.mfaEnabled?'2FA enabled':'Signed in'):'Sign-in required'}</div><div class="stat-bottom"><i class="dot ${auth?'':'gray'}"></i>${auth?'Vault & action controls · View details':'Local setup · View details'}${icon('chevron')}</div></button>
  </div>`;}
function trafficCard(large=false){return `<section class="card"><div class="card-head"><div><h2 class="card-title">${icon('activity')}Network activity</h2><p class="card-subtitle">Receive and send traffic on the HomeBase host.</p></div><div class="card-controls"><span class="live-label"><i class="dot"></i> LIVE</span><div class="segmented" aria-label="Chart time range">${[5,10,15].map(m=>`<button data-range="${m}" class="${state.graphRange===m?'active':''}">${m}m</button>`).join('')}</div></div></div><div class="chart-legend"><span><i class="legend-mark" style="background:var(--mint)"></i>Receive <strong style="font-weight:450;color:#c2dfd6;margin-left:5px">${rate(state.overview.network.rxBps)} Mbps</strong></span><span><i class="legend-mark" style="background:var(--purple)"></i>Send <strong style="font-weight:450;color:#c8c0e2;margin-left:5px">${rate(state.overview.network.txBps)} Mbps</strong></span><span class="chart-summary">LOCAL INTERFACE TRAFFIC</span></div><div class="chart-wrap" ${large?'style="height:310px"':''} id="traffic-chart"></div><div class="chart-foot"><span>${icon('wifi')}${esc(state.overview.network.interface||'Interface awaiting connection')} ${state.overview.network.localAddress?`· ${esc(state.overview.network.localAddress)}`:''}</span><button class="text-button" ${large?'data-action="refresh"':'data-nav="network"'}>${large?'Refresh data':'View network'}${icon(large?'refresh':'arrow')}</button></div></section>`;}
function assistantCard(){const configured=state.settings.ai?.provider && !['none','local'].includes(state.settings.ai.provider);return `<section class="card ai-card"><div class="card-head"><h2 class="card-title">${icon('sparkles')}Your home, a little smarter.</h2><span class="pill">AI ASSISTANT</span></div>${orb()}<div class="ai-card-body"><h3>A helping hand. Always home.</h3><p>Understand your network, manage your devices, and make things happen. Just ask.</p><button class="ai-launch" data-nav="assistant"><span>What can I help you with?</span>${icon('arrow')}</button><div class="ai-privacy">${icon('lock')}${configured?'Your provider. Your control.':'Powered by your local AI · You approve every action'}</div></div></section>`;}
function networkIllustration(){return `<div class="network-illustration" aria-hidden="true"><span>${icon('tv')}</span><span>${icon('router')}</span><span>${icon('server')}</span></div>`;}
function devicesTable(){const d=state.overview.devices;return `<section class="card"><div class="card-head"><h2 class="card-title">${icon('devices')}Connected devices <span class="badge">${d.length}</span></h2><button class="text-button" data-nav="devices">View all${icon('arrow')}</button></div>${d.length?`<table class="device-table"><thead><tr><th>DEVICE</th><th>IP ADDRESS</th><th>STATUS</th><th></th></tr></thead><tbody>${d.slice(0,4).map(device=>`<tr><td><div class="device-name"><span class="device-type-icon">${icon(deviceIcon(device.type))}</span><span>${esc(device.name)}<small>${esc(device.vendor||device.type||'Network device')}</small></span></div></td><td>${esc(device.ip)}</td><td><span class="online ${device.online?'':'offline'}"><i class="dot ${device.online?'':'gray'}"></i>${device.online===true?'Seen recently':device.online===false?'Offline':'Unverified'}</span></td><td><button class="icon-button" data-device="${esc(device.id)}" aria-label="View ${esc(device.name)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table>`:`<div class="table-empty">${networkIllustration()}<h3>A place for every device.</h3><p>When you’re on your home network, discover your devices<br>and bring them together here.</p>${button(state.scanBusy?'Scanning…':'Discover devices','scan',state.scanBusy?'':'scan','ghost',state.scanBusy?'disabled':'')}</div>`}</section>`;}
function quickActions(){return `<section class="card quick-actions"><div class="card-head"><h2 class="card-title">${icon('automations')}Quick actions</h2><span class="card-subtitle" style="margin:0">MAKE IT YOURS</span></div><div class="quick-list">${[['add','plus','Connect a device','Bring something new home'],['connect-ha','home','Set up Home Assistant','Your smart home, in one place'],['approvals','shield','Review approvals',pending().length?`${pending().length} action${pending().length===1?'':'s'} waiting for you`:'You’re always in control']].map(([a,i,t,s])=>`<button class="quick-action" data-action="${a}"><span class="quick-icon">${icon(i)}</span><span><strong>${t}</strong><small>${s}</small></span>${icon('chevron')}</button>`).join('')}</div></section>`;}
function integrationsCard(){return `<section class="card"><div class="card-head"><h2 class="card-title">${icon('box')}Your integrations</h2><button class="text-button" data-settings="integrations">Manage${icon('arrow')}</button></div><div class="integration-grid">${['homeassistant','hikvision','server','ollama'].map(t=>{const i=integration(t);return `<button class="integration-tile" data-connect="${t}" ${i?`data-edit="${esc(i.id)}"`:''}><span class="integration-tile-top">${logo(t)}<strong>${t==='server'?'Raspberry Pi':PROVIDERS[t].name}</strong></span><small><i class="dot ${i?.status==='connected'?'':'gray'}"></i>${i?esc(i.status):'Not connected'}</small></button>`;}).join('')}</div></section>`;}
function systemCard(){const h=state.overview.host;return `<section class="card"><div class="card-head"><h2 class="card-title">${icon('chip')}System health</h2><span class="live-label"><i class="dot ${state.status.authenticated?'':'gray'}"></i> THIS HOST</span></div><div class="system-body"><div class="system-line"><span>CPU usage</span><span>${pct(h.cpuPercent)}</span></div><div class="meter"><i style="width:${Math.min(100,h.cpuPercent||0)}%"></i></div><div class="system-line"><span>Memory</span><span>${pct(h.memoryPercent)} ${h.memoryTotal?`· ${bytes(h.memoryTotal)}`:''}</span></div><div class="meter purple"><i style="width:${Math.min(100,h.memoryPercent||0)}%"></i></div><div class="system-machine">${icon('monitor')}<span>${esc(h.name||'Your local host')}</span><span>${h.uptimeSeconds!=null?`${uptime(h.uptimeSeconds)} uptime`:'Awaiting setup'}</span></div></div></section>`;}
function overview(){return `<div class="overview-heading">`+heading('Your home. All connected.','A clear view of your space. A little more peace of mind.',`${networkIdentityBadge()}${button('Add device','add','plus','secondary')}`)+`</div>`+authBanner()+stats()+`<div class="grid-main">${trafficCard()}${assistantCard()}</div><div class="grid-main">${devicesTable()}${quickActions()}</div><div class="grid-main">${integrationsCard()}${systemCard()}</div>`;}
function deviceIcon(t){t=(t||'').toLowerCase();return /tv|media/.test(t)?'tv':/server|pi/.test(t)?'server':/camera/.test(t)?'camera':/phone|mobile/.test(t)?'phone':/router|gateway/.test(t)?'router':/computer|mac|pc/.test(t)?'monitor':'devices';}
function empty(ic,title,description,action='add',label='Connect an integration'){return `<div class="card empty-state">${icon(ic)}<h3>${title}</h3><p>${description}</p>${button(label,action,'plus','secondary')}</div>`;}
function devicesView(){const filtered=state.overview.devices.filter(d=>(state.deviceFilter==='all'||deviceIcon(d.type)===state.deviceFilter)&&`${d.name} ${d.ip} ${d.vendor}`.toLowerCase().includes(state.deviceSearch.toLowerCase()));const configs=state.overview.integrations.filter(i=>TV_TYPES.includes(i.type)&&`${i.name} ${i.host} ${i.entityId}`.toLowerCase().includes(state.deviceSearch.toLowerCase()));return heading('Everything has a home.','Discover, connect, and get to know the devices on your network.',`${button(state.scanBusy?'Scanning…':'Discover devices','scan','scan','secondary',state.scanBusy?'disabled':'')}${button('Add device','add','plus','')}`,'YOUR DEVICES')+authBanner()+`<div class="toolbar"><div class="tabs">${[['all','All devices'],['tv','Smart TVs'],['server','Servers'],['camera','Cameras']].map(([id,t])=>`<button class="tab ${state.deviceFilter===id?'active':''}" data-filter="${id}">${t}</button>`).join('')}</div><label class="search-field">${icon('search')}<input aria-label="Filter devices" id="device-search" placeholder="Find a device…" value="${esc(state.deviceSearch)}"></label></div>${configs.length&&['all','tv'].includes(state.deviceFilter)?`<div class="grid-cards" style="margin-bottom:22px">${configs.map(tvCard).join('')}</div>`:''}${filtered.length?`<div class="grid-cards">${filtered.map(d=>`<article class="card device-card"><div class="device-card-top"><span class="device-type-icon">${icon(deviceIcon(d.type))}</span><div><h3>${esc(d.name)}</h3><p>${esc(d.vendor||d.type||'Local device')}</p></div><button class="icon-button" data-device="${esc(d.id)}" aria-label="Device details">${icon('chevron')}</button></div><div class="info-row"><span>IP address</span><strong>${esc(d.ip)}</strong></div><div class="info-row"><span>Connectivity</span><strong class="online ${d.online?'':'offline'}"><i class="dot ${d.online?'':'gray'}"></i>${d.online===true?'Recently seen':d.online===false?'Offline':'Unverified'}</strong></div><div class="info-row"><span>Last discovered</span><strong>${date(d.lastSeen)}</strong></div>${d.tvCandidate?`<div class="tv-connect-actions"><button class="btn secondary" data-tv-candidate="${esc(d.id)}">${icon('lock')}Connect TV</button></div>`:''}</article>`).join('')}</div>`:empty('devices',state.deviceSearch?'No devices match your search.':configs.length?'No network discoveries yet.':'Your devices will feel right at home.','Connect your integrations now, or scan when you’re on your home network. You can update every address later.','add','Connect a device')}<div class="note" style="margin:22px 0">${icon('info')}Discovery reads local neighbors, SSDP, and supported TV service advertisements. An online status means recently observed; network isolation and sleeping devices can limit discovery.</div>${serverSection()}`;}
function tvCard(i){const direct=directTV(i),paired=!!i.hasTvCredentials;const protocol=i.protocol||i.type;const ready=!direct||paired;const commands=direct?[['power_off','power','Power off'],['volume_down','minus','Volume down'],['play_pause','pause','Play / pause'],['volume_up','plus','Volume up']].filter(([command])=>protocol!=='webos'||command!=='play_pause'):[['power_on','power','Power on'],['power_off','power','Power off'],['volume_down','minus','Volume down'],['play_pause','pause','Play / pause'],['volume_up','plus','Volume up']];return `<article class="card device-card"><div class="device-card-top">${logo(i.type)}<div><h3>${esc(i.name)}</h3><p>${esc(PROVIDERS[i.type]?.name||'Smart TV')} · ${direct?'Direct network':'Home Assistant'}</p></div><button class="icon-button" data-edit="${esc(i.id)}" aria-label="Edit TV">${icon('settings')}</button></div><div class="info-row"><span>${direct?'Platform':'Entity'}</span><strong>${esc(direct?TV_PLATFORMS[protocol]||protocol:i.entityId||'Select in settings')}</strong></div><div class="info-row"><span>Connection</span><strong>${esc(i.status||'Configured')}</strong></div><div class="tv-remove-row"><button class="text-button" data-delete="${esc(i.id)}" aria-label="Remove ${esc(i.name)} TV connection">${icon('trash')}Remove TV</button></div>${direct?`<div class="tv-connect-actions"><button class="btn secondary" data-pair-tv="${esc(i.id)}">${icon('lock')}${paired?'Pair again':'Pair TV'}</button><button class="btn ghost" data-test="${esc(i.id)}">${icon('refresh')}Check connection</button></div>`:''}<div class="remote-control"><div class="remote-buttons">${commands.map(([command,ic,label])=>`<button data-tv="${esc(i.id)}" data-command="${command}" title="${label}" aria-label="${label}" ${ready?'':'disabled'}>${icon(ic)}</button>`).join('')}${direct&&protocol==='webos'?[['play','play','Play'],['pause','pause','Pause']].map(([command,ic,label])=>`<button data-tv="${esc(i.id)}" data-command="${command}" title="${label}" aria-label="${label}" ${ready?'':'disabled'}>${icon(ic)}</button>`).join(''):''}</div>${i.remoteEntityId||direct?`<div class="remote-pad">${[['up','↑'],['left','←'],['select','OK'],['right','→'],['down','↓'],['home','Home'],['back','Back']].map(([command,label])=>`<button data-tv="${esc(i.id)}" data-command="${command}" aria-label="Remote ${command}" ${ready?'':'disabled'}>${label}</button>`).join('')}</div>`:''}<p class="card-subtitle" style="text-align:center;margin-top:12px">${!ready?'Pair this TV to enable supported controls.':'Commands are reviewed before sending. Platform support varies.'}</p></div></article>`;}

function serverSection(){const configured=state.overview.integrations.filter(i=>i.type==='server');if(!configured.length)return '';return `<div style="margin:28px 0 20px;display:flex;justify-content:space-between"><h2 class="card-title">${icon('server')}Servers & Raspberry Pi</h2><button class="text-button" data-action="servers">Refresh metrics${icon('refresh')}</button></div><div class="grid-cards">${configured.map(i=>{const s=state.servers.find(s=>s.id===i.id);const e=state.serverErrors.find(e=>e.id===i.id);return `<article class="card info-card"><div style="display:flex;align-items:center;gap:12px;margin-bottom:12px">${logo('server')}<h3 style="margin:0;flex:1">${esc(i.name)}</h3><button class="icon-button" data-edit="${esc(i.id)}" aria-label="Edit server">${icon('edit')}</button></div>${[['CPU',pct(s?.cpuPercent)],['Memory',pct(s?.memoryPercent)],['Disk',pct(s?.diskPercent)],['Uptime',uptime(s?.uptimeSeconds)]].map(([k,v])=>`<div class="info-row"><span>${k}</span><strong>${v}</strong></div>`).join('')}<p class="card-subtitle">${e?esc(e.message):s?'Live node_exporter metrics':'Refresh to load node_exporter metrics.'}</p></article>`;}).join('')}</div>`;}
function networkView(){const n=state.overview.network,h=state.overview.host;return heading('A pulse on your network.','Live traffic, real measurements, and a clearer picture of your connections.',button('Scan network','scan','scan','secondary'),'NETWORK INTELLIGENCE')+authBanner()+stats()+`<div style="margin-bottom:22px">${trafficCard(true)}</div><div class="two-column" style="margin-bottom:22px"><section class="card info-card"><h3>Current connection</h3>${[['Interface',n.interface],['Local IP address',n.localAddress],['Gateway',n.gateway],['Gateway latency',n.latencyMs==null?'Scan to start measurement':num(n.latencyMs)+' ms'],['Connectivity',n.connectivity]].map(([k,v])=>`<div class="info-row"><span>${k}</span><strong>${esc(v||'—')}</strong></div>`).join('')}</section><section class="card info-card"><h3>Traffic ≠ internet capacity</h3><p class="subtitle" style="font-size:12px;line-height:1.9">Traffic measures bytes passing through this host’s active interface. It reflects real receive and send throughput, including local traffic.</p><p class="subtitle" style="font-size:12px;line-height:1.9">Latency is the round-trip time to your local gateway, enabled after you start discovery. It may be unavailable if the gateway blocks ICMP.</p><div class="note" style="margin-top:18px">${icon('info')}A quiet host can show 0.37 Mbps on an 82 Mbps connection. This measures current interface usage rather than available internet capacity.</div></section></div>`;}
function camerasView(){
  const cams=state.overview.integrations.filter(i=>i.type==='hikvision');
  const candidates=state.overview.devices.filter(d=>d.cameraCandidate||d.type==='camera');
  const network=state.overview.network;
  const candidateCards=candidates.map(d=>`<article class="card device-card"><div class="device-card-top"><span class="device-type-icon">${icon('camera')}</span><div><h3>${esc(d.name||'Discovered camera')}</h3><p>${esc(d.vendor||'ONVIF / SSDP')} · ${esc(d.ip)}</p></div></div><div class="info-row"><span>Discovery</span><strong>${esc(d.source||'Local advertisement')}</strong></div><div class="info-row"><span>Connection address</span><strong>${esc(d.suggestedHost||d.host||d.ip)}</strong></div><p class="card-subtitle" style="line-height:1.8;margin:14px 0">${d.suggestedIntegration==='hikvision'?'Hikvision candidate. Its address is filled in for you; add an authorized camera username and password.':'Camera advertisement detected. Viewing requires a compatible authorized integration; ONVIF advertising alone does not grant camera access.'}</p><button class="btn secondary" ${d.suggestedIntegration==='hikvision'?`data-camera-candidate="${esc(d.id)}"`:`data-device="${esc(d.id)}"`}>${icon(d.suggestedIntegration==='hikvision'?'lock':'info')}${d.suggestedIntegration==='hikvision'?'Add camera credentials':'View camera details'}</button></article>`).join('');
  return heading('A little more peace of mind.','Automatic local camera discovery. Private, authorized viewing.',`${button('Discover cameras','scan','scan','secondary')}${button('Add camera','connect-camera','plus','secondary')}`,'YOUR CAMERAS')+authBanner()+`<div class="note" style="margin-bottom:22px">${icon('scan')}<strong>${network.discoveryStarted?'Automatic discovery is running every 60 seconds.':network.discoveryPausedReason?esc(network.discoveryPausedReason):'Camera discovery starts automatically with the LAN launcher.'}</strong> ONVIF and SSDP advertisements supply camera addresses. Credentials are never guessed, and devices are never changed. Cameras must advertise on this subnet.</div>`+(cams.length?`<div class="grid-cards">${cams.map(c=>`<article class="card"><div class="camera-frame" id="camera-${esc(c.id)}">${state.cameraUrls[c.id]?`<img src="${esc(state.cameraUrls[c.id])}" alt="Authorized camera snapshot">`:icon('camera')}</div><div class="camera-info"><div><h3>${esc(c.name)}</h3><p>${esc(c.host)} · ISAPI snapshot</p></div><button class="icon-button" data-snapshot="${esc(c.id)}" aria-label="Refresh ${esc(c.name)} snapshot">${icon('refresh')}</button><button class="icon-button" data-edit="${esc(c.id)}" aria-label="Edit camera">${icon('settings')}</button></div></article>`).join('')}</div><div class="note" style="margin:22px 0">${icon('shield')}Snapshots use your encrypted authorized credentials. Continuous RTSP streaming is not enabled.</div>`:'')+`<div class="card-head" style="padding:4px 0 17px"><h2 class="card-title">${icon('scan')}Discovered cameras <span class="badge">${candidates.length}</span></h2><span class="live-label"><i class="dot ${network.discoveryStarted?'':'gray'}"></i>${network.discoveryStarted?'AUTO DISCOVERY':'CURRENT NETWORK'}</span></div>`+(candidates.length?`<div class="grid-cards" style="margin-bottom:24px">${candidateCards}</div>`:empty('camera','Looking out for your cameras.','Cameras advertising ONVIF or SSDP on this network appear here automatically. If discovery is disabled on a camera or it is behind an isolated network or NVR, it may still need a manual address.','scan','Scan for cameras'));
}
function automationsView(){const configured=integration('homeassistant');let entities=state.entities.filter(e=>state.entityFilter==='all'||e.entity_id?.startsWith(state.entityFilter+'.'));entities=entities.filter(e=>['light','switch','scene','script','automation','media_player'].includes(e.entity_id?.split('.')[0]));return heading('Make your home work for you.','Your Home Assistant scenes, automations, and everyday essentials.',button(configured?'Refresh entities':'Connect Home Assistant',configured?'entities':'connect-ha',configured?'refresh':'plus','secondary'),'SMARTER EVERY DAY')+authBanner()+(!configured?empty('automations','A home that’s one step ahead.','Connect your existing Home Assistant to access real entities, run your scenes, and control supported devices. Every action asks for your approval.','connect-ha','Connect Home Assistant'):`<div class="toolbar"><div class="tabs">${[['all','All entities'],['light','Lights'],['scene','Scenes'],['automation','Automations'],['media_player','Media']].map(([id,l])=>`<button class="tab ${state.entityFilter===id?'active':''}" data-entity-filter="${id}">${l}</button>`).join('')}</div></div>${state.entityErrors.map(e=>`<div class="inline-error" style="margin-bottom:18px">${esc(e.message)}</div>`).join('')}<div class="card">${entities.length?entities.map(e=>`<div class="entity-row"><span class="device-type-icon">${icon(e.entity_id.startsWith('light.')?'light':e.entity_id.startsWith('media_player.')?'tv':'automations')}</span><div><h3>${esc(e.attributes?.friendly_name||e.entity_id)}</h3><p>${esc(e.entity_id)} · ${esc(e.state)}</p></div>${['scene','script'].includes(e.entity_id.split('.')[0])?button('Run','entity-service','automations','ghost',`data-entity="${esc(e.entity_id)}" data-integration="${esc(e.integrationId)}"`):`<button class="toggle ${['on','playing'].includes(e.state)?'on':''}" data-action="entity-service" data-entity="${esc(e.entity_id)}" data-integration="${esc(e.integrationId)}" aria-label="Toggle ${esc(e.attributes?.friendly_name||e.entity_id)}"></button>`}</div>`).join(''):`<div class="empty-state">${icon('home')}<h3>No entities loaded yet.</h3><p>Refresh to read your Home Assistant states when you’re on your home network.</p>${button('Load entities','entities','refresh','secondary')}</div>`}</div><div class="note" style="margin:22px 0">${icon('info')}Create or edit automation rules in your existing Home Assistant. Homebase runs your real entities and scenes through its authenticated REST API.</div>`);}
function assistantView(){return heading('Meet your home’s helping hand.','A local assistant with a clear view, and you in control.',button('AI settings','ai-settings','settings','secondary'),'HOME INTELLIGENCE')+authBanner()+`<div class="chat-layout" style="margin-bottom:22px"><section class="card chat-panel"><div class="card-head"><h2 class="card-title">${icon('sparkles')}Homebase assistant</h2>${pill(state.settings.ai?.provider==='ollama'?'Local · Ollama':state.settings.ai?.provider&&state.settings.ai.provider!=='none'?state.settings.ai.provider:'Provider not connected',false)}</div><div class="chat-messages" id="chat-messages">${state.messages.length?state.messages.map(m=>`<div class="message ${m.role}"><div class="message-avatar">${m.role==='user'?'YOU':icon('sparkles')}</div><div class="message-body"><small>${m.role==='user'?'YOU':esc(m.provider||'HOMEBASE')}</small><p>${esc(m.content)}</p>${m.actions?.length?`<button class="btn ghost" style="margin-top:12px" data-action="approvals">${icon('shield')}Review ${m.actions.length} proposed action${m.actions.length===1?'':'s'}</button>`:''}</div></div>`).join(''):`<div class="chat-welcome">${orb()}<h2>A smarter home starts with a hello.</h2><p>Ask about your network, check on your servers, or get help with files in your assistant workspace.</p><div class="suggestions">${['Summarize my network','Check system health','What can you do?'].map(t=>`<button data-prompt="${t}">${t}</button>`).join('')}</div></div>`}${state.chatBusy?`<div class="message"><div class="message-avatar">${icon('sparkles')}</div><div class="message-body"><small>THINKING</small><span class="spinner"></span></div></div>`:''}</div><form class="chat-compose" id="chat-form"><div class="compose-field"><textarea id="chat-input" name="message" rows="1" maxlength="8000" aria-label="Message your assistant" placeholder="Ask anything about your home…" ${state.chatBusy?'disabled':''}></textarea><button type="submit" aria-label="Send message" ${state.chatBusy?'disabled':''}>${icon('send')}</button></div><p class="compose-note">${icon('shield')}You review and approve every file or device action. Enter to send · Shift + Enter for a new line.</p></form></section><aside class="chat-side"><section class="card info-card"><h3>Your assistant, your rules.</h3><p>Connect Ollama for private local inference, or choose your own compatible provider in Settings.</p><div class="capability">${icon('activity')}Understand real network telemetry</div><div class="capability">${icon('tv')}Propose smart device commands</div><div class="capability">${icon('file')}Read and edit workspace files</div><div class="capability">${icon('shield')}Explicit approval for every action</div><button class="btn ghost" data-action="ai-settings" style="margin-top:22px;width:100%">Configure provider${icon('arrow')}</button></section><section class="card info-card"><h3>Assistant workspace</h3><p class="break">${esc(state.settings.workspace||'Available after secure setup')}</p><p>File access stays inside this folder. Approve a file read before asking the assistant to edit its contents.</p><button class="text-button" data-action="approvals">Review activity${icon('arrow')}</button></section></aside></div>`;}

function settingsView(){const tabs=[['integrations','box','Integrations'],['ai','sparkles','AI & workspace'],['security','shield','Security'],['deployment','server','Deployment']];return heading('Built around your home.','Your connections, your assistant, your rules. All in one place.','','WORKSPACE SETTINGS')+authBanner()+`<div class="settings-layout" style="margin-bottom:25px"><nav class="settings-nav" aria-label="Settings sections">${tabs.map(([id,ic,t])=>`<button class="${state.tab===id?'active':''}" data-settings="${id}">${icon(ic)}${t}</button>`).join('')}</nav><div class="settings-panel">${({integrations:integrationSettings,ai:aiSettings,security:securitySettings,deployment:deploymentSettings}[state.tab]||integrationSettings)()}</div></div>`;}
function integrationSettings(){const items=state.overview.integrations;return `<section class="card"><div class="section-intro" style="display:flex;align-items:center;gap:20px"><div style="flex:1"><h2>Your connections</h2><p>Manage local services, paired TVs, and encrypted credentials.</p></div>${button('Add','add','plus','secondary')}</div>${items.length?items.map(i=>`<div class="integration-list-item">${logo(i.type)}<div><h3>${esc(i.name)}</h3><p>${esc(i.host)}${i.entityId?` · ${esc(i.entityId)}`:''}</p>${i.message?`<p style="margin-top:5px">${esc(i.message)}</p>`:''}</div>${pill(i.status||'Configured',i.status==='connected')}<div class="integration-buttons"><button class="icon-button" data-test="${esc(i.id)}" title="Test connection" aria-label="Test ${esc(i.name)}">${icon('refresh')}</button><button class="icon-button" data-edit="${esc(i.id)}" title="Edit settings" aria-label="Edit ${esc(i.name)}">${icon('edit')}</button><button class="icon-button" data-delete="${esc(i.id)}" title="Remove integration" aria-label="Remove ${esc(i.name)}">${icon('trash')}</button></div></div>`).join(''):`<div class="empty-state" style="min-height:240px">${icon('network')}<h3>Good things work better together.</h3><p>Add your first integration. Credentials stay encrypted on this host, and no connection is tested until you ask.</p>${button('Explore integrations','add','plus','secondary')}</div>`}</section><div class="note" style="margin-top:18px">${icon('info')}Supported TVs can connect directly on the same network. Home Assistant remains available for automations. Server metrics use node_exporter; camera snapshots require authorized ISAPI credentials.</div>`;}
function field(label,name,value='',placeholder='',type='text',help='',attributes=''){return `<label class="field"><span class="field-label">${label}</span><input type="${type}" name="${name}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${attributes}>${help?`<small>${help}</small>`:''}</label>`;}
function aiSettings(){const a=state.settings.ai||{};return `<section class="card"><div class="section-intro"><h2>A home for your intelligence</h2><p>Connect an Ollama server on your network, or configure a compatible AI provider.</p></div><form id="ai-settings-form" class="form-body"><label class="field"><span class="field-label">AI provider</span><select name="provider" id="ai-provider"><option value="ollama" ${a.provider==='ollama'?'selected':''}>Ollama · local inference</option><option value="openai-compatible" ${['openai','openai-compatible'].includes(a.provider)?'selected':''}>OpenAI-compatible · configured endpoint</option><option value="none" ${['none','local'].includes(a.provider)?'selected':''}>Local status only · no model</option></select></label>${field('Provider base URL','baseUrl',a.baseUrl||'http://127.0.0.1:11434','http://127.0.0.1:11434','url','Ollama stays on your private network. A remote provider uses HTTPS and receives your chat, selected telemetry, and approved file reads.','maxlength="2048"')}
  <div class="form-grid">${field('Model','model',a.model||'','qwen3:4b','text','Choose a model installed on your provider. Smaller tool-capable models respond faster.','maxlength="200"')}${field('API key (optional)','apiKey','','Leave blank to keep stored key','password','Encrypted on this host. Never returned to the browser.','autocomplete="new-password"')}</div><div style="margin-top:12px"><button type="button" class="text-button" data-action="models">Load models from saved provider${icon('refresh')}</button><div id="model-results"></div></div>${field('Assistant workspace','workspace',state.settings.workspace||'','','text','An existing, dedicated local folder. File reads and edits require individual approval and stay within this folder.')}<div id="settings-error"></div><div class="form-actions"><button class="btn" type="submit">${icon('check')}Save configuration</button></div></form></section><div class="note" style="margin-top:18px">${icon('shield')}The assistant can propose file edits and supported network actions. It cannot execute shell commands or approve its own actions. Actual speed depends on your model and hardware.</div>`;}
function securitySettings(){const s=state.settings.security||{};const verified=[
  ['shield','Encrypted credential vault','Saved credentials use AES-256-GCM. The master key is stored on this host.',s.encryptedStorage?'Active':'Not verified',s.encryptedStorage],
  ['lock','Local administrator account','Scrypt password hashing, rate-limited sign-in, and same-site session cookies.',s.accountConfigured?'Configured':'Setup needed',s.accountConfigured],
  ['file','Vault key permissions','Checks the owner and permission bits of the local key file. Host administrators can still access it.',s.keyPermissionsRestricted===true?'Owner only':s.keyPermissionsRestricted===false?'Needs attention':'Not verified',s.keyPermissionsRestricted===true],
  ['shield','Action approval','Proposed device commands and assistant file reads or writes wait for a separate approval.',s.approvalRequired?'Required':'Not verified',s.approvalRequired],
  ['globe','Network access',s.https?(s.lanEnabled?'HTTPS with private-network client checks.':'HTTPS enabled on the configured local listener.'):'HTTP is limited to loopback; LAN access requires HTTPS.',s.https?'HTTPS':'Loopback only',s.https]
];return `<section class="card"><div class="section-intro"><h2>Security you can inspect.</h2><p>Verified application controls for your account, credentials, and actions.</p></div>${verified.map(([i,t,d,p,active])=>`<div class="security-feature">${icon(i)}<div><strong>${t}</strong><p>${d}</p></div>${pill(p,!!active)}</div>`).join('')}<div class="security-feature">${icon('phone')}<div><strong>Two-factor authentication</strong><p>${s.mfaEnabled?'Authenticator codes are required at sign-in.':'Add a rotating code from your authenticator app.'}</p></div>${s.mfaEnabled?pill('Enabled',true):button('Enable','mfa','plus','secondary')}</div><div class="security-feature">${icon('logout')}<div><strong>Current session</strong><p>${state.status.authenticated?`Signed in as ${esc(state.status.user)} · ${esc(s.sessionIdleMinutes||30)}-minute idle timeout`:'Sign in to manage your account.'}</p></div>${button('Sign out','logout','','ghost')}</div></section><div class="note" style="margin-top:18px">${icon('info')}These controls protect HomeBase application data and govern supported actions. They do not assess the security of your whole home or network. Permission checks cover file modes and ownership, not every possible operating-system ACL.</div>${lanDetails()}<div class="note" style="margin-top:18px">${icon('info')}Keep the encrypted vault and its master key together in a private backup. The portable source excludes credentials and runtime data. Full-disk encryption can add protection against physical access.</div>`;}

function lanDetails(){const lan=state.overview.lan||{};return `<section class="card info-card" style="margin-top:20px"><h3>Your local network address</h3><div class="info-row"><span>HTTPS dashboard</span><strong>${lan.url?`<a href="${esc(lan.url)}">${esc(lan.url)}</a>`:'LAN launcher is not enabled'}</strong></div><div class="info-row"><span>Bonjour discovery</span><strong>${esc(lan.advertisementState||'Disabled')}</strong></div><div class="info-row"><span>Device discovery at startup</span><strong>${lan.autoDiscover?'Enabled':'Disabled'}</strong></div>${lan.advertisementError?`<p class="subtitle">${esc(lan.advertisementError)}</p>`:''}<p class="subtitle" style="line-height:1.8">Trust your own homebase-rootCA.crt on each device before signing in. Devices must be on the same network with multicast allowed. The direct private IP address also works when present in the certificate.</p></section>`;}
function deploymentSettings(){return `<section class="card"><div class="section-intro"><h2>Your home. Your hardware.</h2><p>Run HomeBase OS on Raspberry Pi OS Lite (64-bit) with Docker Compose.</p></div><div class="form-body"><h3 class="card-title" style="margin:14px 0">Install on a Raspberry Pi</h3><pre class="code"># Inside the downloaded HomeBase source folder
sudo ./scripts/setup-pi.sh</pre><p class="subtitle">The terminal wizard creates a local administrator, generates private HTTPS certificates, and starts automatic device discovery. Docker must already be installed.</p><h3 class="card-title" style="margin:24px 0 12px">Open from any device at home</h3><p class="subtitle" style="line-height:1.9">Use the HTTPS address shown below on the same network. Trust the generated public root certificate on each client before signing in. Discovery depends on multicast reaching your devices.</p>${lanDetails()}<div class="note" style="margin-top:20px">${icon('info')}README.md and docs/INSTALL.md include the terminal tutorial, backups, updates, and troubleshooting. Runtime accounts, keys, and credentials stay outside the source distribution.</div><div class="form-actions">${button('Getting started','help','info','secondary')}</div></div></section>`;}

function render(){const views={overview,devices:devicesView,network:networkView,cameras:camerasView,automations:automationsView,assistant:assistantView,settings:settingsView};$('#app').innerHTML=shell((views[state.page]||overview)());drawChart();if(state.page==='assistant')requestAnimationFrame(()=>{const m=$('#chat-messages');if(m)m.scrollTop=m.scrollHeight;});}
function drawChart(){const container=$('#traffic-chart');if(!container)return;const cutoff=Date.now()-state.graphRange*60000;const all=state.overview.network.history||[];const history=all.filter(p=>new Date(typeof p.time==='number'?p.time*1000:p.time).getTime()>=cutoff&&p.rxBps!=null&&p.txBps!=null);const w=700,h=202,left=48,right=12,top=19,bottom=28,ph=h-top-bottom,pw=w-left-right;const max=Math.max(...history.flatMap(p=>[p.rxBps*8/1e6,p.txBps*8/1e6]),.1)*1.15;
  const lines=Array.from({length:5},(_,i)=>{const y=top+i*ph/4;return `<line x1="${left}" x2="${w-right}" y1="${y}" y2="${y}" stroke="#2b3342" stroke-dasharray="3 5" stroke-opacity=".7"/><text x="${left-12}" y="${y+3}" text-anchor="end" fill="#68778f" font-size="8" font-family="inherit">${num(max*(1-i/4),max<1?2:1)}</text>`;}).join('');
  const x=i=>left+i*pw/Math.max(history.length-1,1),y=v=>top+ph-v*8/1e6/max*ph;
  const path=k=>history.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(p[k]).toFixed(1)}`).join(' ');
  const area=k=>history.length>1?path(k)+` L${x(history.length-1)},${top+ph} L${left},${top+ph} Z`:'';
  const times=Array.from({length:6},(_,i)=>{const index=Math.round(i*(history.length-1)/5);const time=history[index]?.time;return `<text x="${left+i*pw/5}" y="${h-8}" text-anchor="${i===0?'start':i===5?'end':'middle'}" fill="#68778f" font-size="8" font-family="inherit">${time?esc(date(time)):i===5?'now':`${state.graphRange-Math.round(i*state.graphRange/5)}m ago`}</text>`;}).join('');
  container.innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Live receive and send interface throughput in megabits per second"><defs><linearGradient id="receive-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#79e7cd" stop-opacity=".17"/><stop offset="1" stop-color="#79e7cd" stop-opacity="0"/></linearGradient><linearGradient id="send-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#a396ff" stop-opacity=".12"/><stop offset="1" stop-color="#a396ff" stop-opacity="0"/></linearGradient></defs>${lines}<path d="${area('rxBps')}" fill="url(#receive-fill)"/><path d="${area('txBps')}" fill="url(#send-fill)"/><path d="${path('rxBps')}" fill="none" stroke="#79e7cd" stroke-width="1.8" vector-effect="non-scaling-stroke"/><path d="${path('txBps')}" fill="none" stroke="#a396ff" stroke-width="1.8" vector-effect="non-scaling-stroke"/>${times}<line id="chart-hover-line" x1="0" x2="0" y1="${top}" y2="${top+ph}" stroke="#b2bed0" stroke-dasharray="3 4" opacity="0"/></svg>${history.length<2?'<div class="chart-empty">'+(state.status.authenticated?'Collecting live interface samples…':'Your network story starts here.')+'</div>':''}<div class="chart-tooltip"></div>`;
  container.onpointermove=event=>{if(history.length<2)return;const rect=container.getBoundingClientRect();const local=(event.clientX-rect.left)/rect.width*w;const index=Math.round(Math.max(0,Math.min(1,(local-left)/pw))*(history.length-1));const p=history[index],line=$('#chart-hover-line',container),tip=$('.chart-tooltip',container);line.setAttribute('x1',x(index));line.setAttribute('x2',x(index));line.setAttribute('opacity','.6');tip.style.display='block';tip.style.left=`${Math.max(15,Math.min(rect.width-170,event.clientX-rect.left+12))}px`;tip.innerHTML=`<span style="color:#8193b0">${esc(date(p.time))}</span><br><span style="color:var(--mint)">↓ ${rate(p.rxBps)} Mbps</span> &nbsp; <span style="color:var(--purple)">↑ ${rate(p.txBps)} Mbps</span>`;};container.onpointerleave=()=>{$('.chart-tooltip',container).style.display='none';$('#chart-hover-line',container).setAttribute('opacity','0');};
}

let previousFocus;
function openModal(title,description,body,{wide=false,kind='generic',closable=true}={}){previousFocus=document.activeElement;state.modal=kind;$('#modal-root').innerHTML=`<div class="modal-shade"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${description}</p></div>${closable?`<button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button>`:''}</div><div class="modal-body">${body}</div></section></div>`;$('.workspace')?.setAttribute('inert','');$('.sidebar')?.setAttribute('inert','');requestAnimationFrame(()=>$('.modal input, .modal button, .modal select')?.focus());}
function closeModal(){if(state.modal==='pairing'&&state.pairing?.pairingId){const p=state.pairing;api(`/tvs/${encodeURIComponent(p.integrationId)}/pair/cancel`,{pairingId:p.pairingId}).catch(()=>{});}if(state.modal==='pairing')state.pairing=null;const identityDialog=state.modal==='network-identity';state.modal=null;$('#modal-root').innerHTML='';$('.workspace')?.removeAttribute('inert');$('.sidebar')?.removeAttribute('inert');if(identityDialog&&state.page==='overview')render();previousFocus?.focus();}
function requireAuth(){if(state.status.authenticated)return true;authModal();return false;}
function authModal(){const setup=state.status.setupRequired;openModal(setup?'Your home. Your private space.':'Welcome home.','A secure local account, just for your command centre.',`<div class="brand-mark">${icon('home')}</div><form id="auth-form" autocomplete="on">${field('Username','username','','Your username','text','','required autocomplete="username" pattern="[A-Za-z0-9_.-]+" maxlength="64"')}${field('Password','password','','', 'password',setup?'Use a unique password with at least 14 characters.':'','required autocomplete="'+(setup?'new-password':'current-password')+'" '+(setup?'minlength="14"':'')+' maxlength="1024"')}${setup?field('Confirm password','confirm','','','password','','required autocomplete="new-password" minlength="14"'):field('Authenticator code (if enabled)','totp','','6-digit code','text','','inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6"')}<div id="auth-error"></div><div class="form-actions"><button class="btn" type="submit" style="width:100%">${icon('shield')}${setup?'Create secure account':'Sign in securely'}</button></div></form><div class="auth-foot">${icon('lock')}Stored on this host. Never sent to a cloud.</div>`,{kind:'auth'});}
function providerPicker(){if(!requireAuth())return;openModal('Bring your home together.','Choose an integration. You can save addresses now and connect on your home network later.',`<div class="provider-choices">${Object.entries(PROVIDERS).map(([type,p])=>`<button class="provider-choice" data-connect="${type}">${logo(type)}<div><strong>${p.name}</strong><small>${p.detail}</small></div>${icon('chevron')}</button>`).join('')}</div><div class="note" style="margin-top:19px">${icon('shield')}Saving connection details does not send commands or pair devices.</div>`,{wide:true,kind:'providers'});}
function connectionModal(type,config={}){
  if(!requireAuth())return;
  const p=PROVIDERS[type];if(!p)return;
  const tv=TV_TYPES.includes(type),direct=tv&&(config.id?directTV(config):true),protocol=config.protocol||(type==='hisense'?'androidtv':type);
  const gateways=state.overview.integrations.filter(i=>i.type==='homeassistant');
  openModal(config.id?'Connection settings.':`Connect ${p.name}.`,tv?'Pair supported TVs directly over your local network, or use an existing Home Assistant gateway.':type==='server'?'Connect an existing Prometheus node_exporter.':'Add your authorized connection details.',`<form id="integration-form" data-type="${type}" ${config.id?`data-id="${esc(config.id)}"`:''}>
    <div style="margin:3px 0 20px">${logo(type)}</div>
    ${field('Display name','name',config.name||'',p.name,'text','','required maxlength="80"')}
    ${tv?`<label class="field"><span class="field-label">Connection method</span><select id="tv-connection-mode" name="connectionMode"><option value="direct" ${direct?'selected':''}>Direct · no Home Assistant needed</option><option value="homeassistant" ${!direct?'selected':''}>Through Home Assistant</option></select></label>`:''}
    ${field(tv?(direct?'TV address':'Home Assistant URL'):'Host / base URL','host',config.host||'',tv?(direct?'192.168.1.50':'http://homeassistant.local:8123'):p.host,'text','Use a private IP address or local hostname. Include the port if needed.','required maxlength="2048"')}
    ${tv?`<fieldset class="plain-fieldset" id="tv-direct-fields" ${direct?'':'hidden disabled'}><label class="field"><span class="field-label">TV platform</span><select name="protocol" id="tv-protocol">${Object.entries(TV_PLATFORMS).map(([id,name])=>`<option value="${id}" ${id===protocol?'selected':''}>${name}</option>`).join('')}</select></label><p class="protocol-note">Hisense TVs use different platforms: choose Google / Android TV or Roku when that is what your TV runs. VIDAA-only models are not covered by a universal network API. The TV and server must share a network with device isolation disabled.</p><div id="tv-local-channel-note" ${insecureTV(protocol)?'':'hidden'} class="note">${icon('info')}Samsung, LG, and Roku use vendor local control channels that can be unencrypted. Pairing asks you to allow that specific local connection. Android TV and Apple TV use their pairing protocols.</div><p class="protocol-note">Save first, then choose Pair TV in Devices. Pairing codes and on-screen approvals are handled in the next step; no commands are sent by saving.</p></fieldset>
    <fieldset class="plain-fieldset" id="tv-ha-fields" ${!direct?'':'hidden disabled'}>${gateways.length?`<label class="field"><span class="field-label">Saved Home Assistant gateway (optional)</span><select name="homeAssistantId"><option value="">Use credentials below</option>${gateways.map(g=>`<option value="${esc(g.id)}" ${g.id===config.homeAssistantId?'selected':''}>${esc(g.name)}</option>`).join('')}</select><small>A saved gateway supplies its encrypted access token.</small></label>`:''}${field('Long-lived access token','token','','Leave blank to keep stored token','password','Use a saved gateway or provide an authorized token.','autocomplete="new-password"')}${field('Media player entity','entityId',config.entityId||'','media_player.living_room_tv','text','Choose an existing paired Home Assistant entity.','required pattern="media_player\\.[a-z0-9_]+"')}${field('Remote entity (optional)','remoteEntityId',config.remoteEntityId||'','remote.living_room_tv','text','Enables supported Home Assistant navigation commands.')}</fieldset>`:''}
    ${type==='hikvision'?`<div class="form-grid">${field('Username','username',config.username||'','','text','','required autocomplete="off"')}${field('Password','password','','','password',config.id?'Leave blank to keep the saved password.':'Use an account authorized for camera snapshots.',`${config.id?'':'required'} autocomplete="new-password"`)}</div>${field('ISAPI channel','channel',config.channel||101,'101','number','For an NVR, 101 commonly means channel 1, main stream.','required min="1" max="99999"')}`:''}
    ${type==='homeassistant'?field('Long-lived access token','token','','Leave blank to keep stored token','password','Create this in your Home Assistant profile.','autocomplete="new-password"'):''}
    ${type==='server'?field('Bearer token (optional)','token','','Leave blank to keep stored token','password','For an authenticated exporter proxy.','autocomplete="new-password"')+field('Metrics path','monitoringPath',config.monitoringPath||'/metrics','/metrics','text','node_exporter usually listens on port 9100.'):''}
    ${type==='ollama'?`<div class="note">${icon('info')}This saves a health-check connection. Configure the assistant’s model under AI & workspace.</div>`:''}
    <div id="integration-error"></div><div class="form-actions">${config.id?`<button class="btn ghost" type="button" data-delete="${esc(config.id)}">${icon('trash')}${tv?'Remove TV':'Remove connection'}</button>`:''}${button('Cancel','close','','ghost')}<button class="btn" type="submit">${icon('check')}${config.id?'Save changes':'Save connection'}</button></div></form>`,{kind:'integration'});
}
function pairingModal(config){
  if(!requireAuth())return;
  const insecure=insecureTV(config.protocol||config.type);
  state.pairing={integrationId:config.id};
  openModal(`Pair ${esc(config.name)}.`,`Direct connection · ${esc(config.host)}`,`<p class="subtitle" style="line-height:1.9">Turn on the TV and keep it on the same network as HomeBase. Starting pairing may display an approval prompt or pairing code on the TV. This will authorize HomeBase as a remote for this TV.</p>${insecure?`<label class="checkbox-field" style="margin:18px 0"><input id="pair-insecure-consent" type="checkbox"><span>I allow this TV’s unencrypted local control channel on my trusted home network.</span></label>`:''}<div id="pairing-content"></div><div id="pairing-error"></div><div class="tv-remove-row"><button class="text-button" data-delete="${esc(config.id)}">${icon('trash')}Remove saved TV</button></div><div class="form-actions" id="pairing-start-actions">${button('Cancel','close','','ghost')}${button('Approve & start pairing','pair-start','lock','',`data-id="${esc(config.id)}"`)}</div>`,{kind:'pairing'});
}
async function startPairing(el){
  const config=state.overview.integrations.find(i=>i.id===el.dataset.id);if(!config)return;
  if(insecureTV(config.protocol||config.type)&&!$('#pair-insecure-consent')?.checked)throw new Error('Tick the local-channel consent box to pair this platform.');
  el.disabled=true;
  try{
    if(insecureTV(config.protocol||config.type)&&!config.allowInsecureLocalControl){await api('/integrations',{...config,connectionMode:'direct',allowInsecureLocalControl:true});await refresh(false);}
    const data=await api(`/tvs/${encodeURIComponent(config.id)}/pair/start`,{approved:true});
    if(state.modal!=='pairing'){if(data.pairingId)await api(`/tvs/${encodeURIComponent(config.id)}/pair/cancel`,{pairingId:data.pairingId});return;}
    state.pairing={...data,integrationId:config.id};
    $('#pairing-start-actions').hidden=true;
    const checkbox=$('#pair-insecure-consent');if(checkbox)checkbox.disabled=true;
    $('#pairing-content').innerHTML=`<div class="pairing-status">${icon('tv')} ${esc(data.message)}<br><small>This pairing session expires at ${date(data.expiresAt)}.</small></div><form id="tv-pair-form">${data.requiresCode?field('Pairing code shown on TV','code','','Enter TV code','text','Keep the TV’s pairing screen open.','required class="pairing-code" autocomplete="one-time-code" maxlength="16" spellcheck="false"'):''}<div class="form-actions"><button class="btn" type="submit">${icon('check')}${data.requiresCode?'Complete pairing':'I allowed it on the TV · Complete pairing'}</button></div></form>`;
    $('#tv-pair-form input')?.focus();
  }catch(e){modalError('#pairing-error',e);}finally{el.disabled=false;}
}

function approvalsModal(){if(!requireAuth())return;const actions=[...(state.overview.actions||[])].reverse();openModal('You’re always in control.','Inspect the exact target and payload before approving. Each approval runs once and expires after 15 minutes.',`<div class="action-list">${actions.length?actions.map(a=>`<article class="action-item"><h3>${esc(a.type)} <span class="badge" style="float:right">${esc(a.status==='pending'&&a.expiresAt<Date.now()/1000?'expired':a.status)}</span></h3><p>${esc(state.overview.integrations.find(i=>i.id===a.target)?.name||a.target)} · ${esc(a.source||'you')} · ${date(a.createdAt)}</p><pre class="code">${esc(JSON.stringify(a.payload,null,2))}</pre>${a.status==='pending'&&a.expiresAt>Date.now()/1000?`<div class="form-actions"><button class="btn ghost" data-reject="${esc(a.id)}">Reject</button><button class="btn" data-approve="${esc(a.id)}">${icon('check')}Approve & execute</button></div>`:''}${a.error?`<div class="inline-error">${esc(a.error)}</div>`:''}${a.result?`<p style="margin-top:15px">Result</p><pre class="code">${esc(typeof a.result==='string'?a.result:JSON.stringify(a.result,null,2))}</pre>`:''}</article>`).join(''):`<div class="empty-state" style="min-height:230px">${icon('shield')}<h3>Nothing waiting on you.</h3><p>Device commands and assistant file actions will appear here before anything happens.</p></div>`}</div>`,{wide:true,kind:'approvals'});}
function activityModal(){if(!requireAuth())return;openModal('A little peace of mind.','Recent local activity and actions awaiting your review.',`${pending().length?`<div class="setup-banner"><div><strong>${pending().length} pending approval${pending().length===1?'':'s'}</strong><p>No actions have been sent.</p></div>${button('Review','approvals','shield','secondary')}</div>`:''}<div>${state.overview.events.length?[...state.overview.events].sort((a,b)=>(b.time||b.timestamp)-(a.time||a.timestamp)).slice(0,20).map(e=>`<div class="entity-row" style="padding-left:0;padding-right:0"><span class="device-type-icon">${icon(e.kind==='security'?'shield':e.kind==='approval'?'check':'activity')}</span><div><h3>${esc(e.title)}</h3><p>${esc(e.detail)}</p></div><small style="font-size:9px;color:var(--dim)">${date(e.time||e.timestamp)}</small></div>`).join(''):'<p class="subtitle">Activity will appear here as you use Homebase.</p>'}</div>`,{kind:'activity'});}
function helpModal(){openModal('Make yourself at home.','HomeBase OS runs on your hardware, with your own local account.',`<div class="action-list">${[['1','Create a secure account','The terminal setup creates your administrator. Enable two-factor authentication in Settings → Security.'],['2','Discover the network','Open Devices and start discovery. TVs and cameras that advertise supported local services appear without Home Assistant.'],['3','Pair a supported TV','Choose a discovered TV or enter its local address. Approve the connection on the TV, or enter the pairing code it displays. Support depends on the TV platform and model.'],['4','Connect services','Add authorized camera credentials, server metrics, an AI provider, and optional Home Assistant automations.'],['5','Review before action','Commands and assistant file changes wait in Approvals. Inspect the target and payload, then approve or reject.']].map(([n,t,d])=>`<div class="security-feature" style="padding-left:0;padding-right:0"><span class="badge">${n}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div><div class="note" style="margin-top:18px">${icon('info')}See README.md and docs/INSTALL.md for the Raspberry Pi Docker tutorial. Camera viewing uses authenticated JPEG snapshots. Discovery never bypasses pairing or device credentials.</div>`,{kind:'help'});}
function workspaceModal(){
  if(!requireAuth())return;
  openModal('Your workspace.','Name this HomeBase installation and jump to its settings.',`<form id="workspace-form">${field('Workspace name','workspaceName',state.settings.workspaceName||'My home','My home','text','This is a display name for this installation.','required minlength="1" maxlength="64" autocomplete="off"')}<div id="workspace-error"></div><div class="form-actions"><button class="btn" type="submit">${icon('check')}Save name</button></div></form><div class="workspace-shortcuts">${button('Connections','workspace-integrations','box','secondary')}${button('App security','security-details','shield','secondary')}${button('Installation','workspace-deployment','server','secondary')}</div><div class="note">${icon('info')}One HomeBase installation manages one local workspace. Pair TVs in Devices and connect automation services in Settings.</div>`,{kind:'workspace'});
}
function securityDetailsModal(){const s=state.overview.security||state.settings.security||{};openModal('Security you can inspect.','These controls apply to HomeBase accounts, saved credentials, and actions.',`<div>${[['Local account',s.accountConfigured?'Configured':'Not configured'],['Encrypted credential storage',s.encryptedStorage?'AES-256-GCM active':'Not verified'],['Key file permissions',s.keyPermissionsRestricted===true?'Owner only':s.keyPermissionsRestricted===false?'Needs attention':'Not verified'],['HTTPS',s.https?'Enabled':'Disabled · loopback only'],['Two-factor sign-in',s.mfaEnabled?'Enabled':'Not enabled'],['Action approval',s.approvalRequired?'Required before commands and file actions':'Not verified']].map(([k,v])=>`<div class="info-row"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><p class="subtitle" style="line-height:1.9;margin-top:18px">The encrypted vault holds saved integration credentials. Its master key stays on the host, so a host administrator can access it. Approval means a proposed device command or assistant file action waits for you to inspect it and click “Approve & execute”. Discovery only reads advertisements.</p><div class="note" style="margin-top:18px">${icon('info')}This is the application’s security status. It does not assess your router, cameras, network, or physical home.</div><div class="form-actions">${button('Review approvals','approvals','check','secondary')}${button('Security settings','security-settings','shield','')}</div>`,{kind:'security-details'});}


async function networkIdentityModal(){
  if(!requireAuth())return;
  const [identity,settings]=await Promise.all([api('/network-identity'),api('/settings')]);
  state.overview.networkIdentity=identity;state.settings=settings;
  const config=settings.networkIdentity||{},isp=identity.isp||{},router=identity.router||{},automatic=!config.ispName;
  const detected=identity.detectedIsp||(isp.source!=='manual'?isp:{});
  const providers=['Telstra','Optus','Exetel','Aussie Broadband','Superloop','TPG','iiNet','Dodo','Vodafone','Belong','Tangerine','Spintel','More','AGL','Southern Phone','Starlink'];
  const routerChoices=Object.values(BRAND_LOGOS).filter(b=>b.roles.includes('router')).map(b=>b.name);
  openModal('A familiar face for your network.','Your internet provider and router brand, neatly at home on the overview.',`
    <div class="identity-preview" inert>${networkIdentityBadge()}</div>
    <form id="network-identity-form">
      <label class="field"><span class="field-label">ISP identification</span><select id="isp-mode" name="ispMode"><option value="automatic" ${automatic?'selected':''}>Automatic — use the detected provider</option><option value="manual" ${automatic?'':'selected'}>Manual — choose my provider</option></select></label>
      <div id="manual-isp-field" ${automatic?'hidden':''}>${field('Internet provider','ispName',config.ispName||'','Enter your ISP','text','This name is used only in Manual mode.','list="isp-options" maxlength="160" '+(automatic?'disabled':''))}<datalist id="isp-options">${providers.map(name=>`<option value="${esc(name)}"></option>`).join('')}</datalist></div>
      <div class="identity-auto-status" id="automatic-isp-description" ${automatic?'':'hidden'}>${icon('globe')}<div><strong>${esc(detected.name||'No automatic result yet')}</strong><small>${detected.detectedAt?`Last detected at ${esc(date(detected.detectedAt))}. `:''}Use Auto-detect to make a fresh check and replace any manual selection.</small></div></div>
      ${field('Router company','routerName',config.routerName||'','Use detected manufacturer, or enter a brand','text','A known router shows its logo. Otherwise the provider logo or a neutral network icon is shown.','list="router-options" maxlength="160"')}
      <datalist id="router-options">${routerChoices.map(name=>`<option value="${esc(name)}"></option>`).join('')}</datalist>
      <label class="consent-checkbox"><input type="checkbox" name="allowExternalLookup" ${config.allowExternalLookup?'checked':''}><span><strong>Check ISP changes every minute</strong><small>Checks the public IP with ipify every 60 seconds and refreshes the ISP through ipwho.is when it changes. Both see your public IP; credentials and device details stay here.</small></span></label>
      <div class="note" style="margin-top:18px">${icon('info')}Detection reports the current internet exit network. A VPN, hotspot, or wholesale network can differ from your retail ISP. It cannot see through a VPN to identify the underlying connection.</div>
      <div class="identity-evidence"><span>Provider mode: ${isp.source==='manual'?'Manual selection':'Automatic detection'}${isp.source==='ipwho.is'?' · ipwho.is':''}</span><span>Router: ${esc(router.source||'not detected')}${router.ip?` · ${esc(router.ip)}`:''}</span></div>
      ${isp.message?`<p class="subtitle">${esc(isp.message)}</p>`:''}<div id="identity-error"></div>
      <div class="form-actions identity-form-actions"><button type="button" class="btn ghost" data-action="detect-isp">${icon('globe')}Auto-detect ISP now</button><button class="btn" type="submit">${icon('check')}Save appearance</button></div>
      <p class="identity-detection-note">Auto-detect switches to Automatic mode after a successful fresh lookup. A failed lookup keeps your manual choice and shows an error. Logos load locally.</p>
    </form>`,{kind:'network-identity'});
}

async function navigate(page,tab){closeModal();state.sidebarOpen=false;$('#sidebar')?.classList.remove('open');state.page=page;if(tab)state.tab=tab;history.replaceState(null,'','#'+page);if(page==='settings'&&state.status.authenticated){try{state.settings=await api('/settings');}catch(e){toast(e.message,true);}}render();window.scrollTo(0,0);if(page==='devices'&&state.overview.integrations.some(i=>i.type==='server'&&i.status==='connected'))loadServers();}
async function loadServers(){if(!requireAuth())return;try{const data=await api('/servers');state.servers=data.servers||[];state.serverErrors=data.errors||[];state.serversLive=state.servers.length>0;if(state.page==='devices'&&!state.modal&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))render();}catch(e){toast(e.message,true);}}
async function loadEntities(){if(!requireAuth())return;try{toast('Reading Home Assistant entities…');const data=await api('/entities');state.entities=(data.entities||[]).map(e=>({...e,entity_id:e.entityId||e.entity_id}));state.entityErrors=data.errors||[];render();if(data.errors?.length)toast(data.errors[0].message,true);else toast(`${state.entities.length} entities loaded.`);}catch(e){toast(e.message,true);}}
async function propose(type,target,payload){if(!requireAuth())return;await api('/actions',{type,target,payload});await refresh(false);approvalsModal();}
function searchModal(){openModal('Find your way home.','Jump to a page or find a discovered device.',`<label class="search-field">${icon('search')}<input id="global-search" placeholder="Devices, cameras, settings…" aria-label="Search pages and devices" autocomplete="off"></label><div id="search-results" class="search-results"></div>`,{kind:'search'});searchResults('');}
function searchResults(query){const q=query.toLowerCase();const pages=[...NAV,['settings','settings','Settings']].filter(n=>n[2].toLowerCase().includes(q));const devices=state.overview.devices.filter(d=>`${d.name} ${d.ip}`.toLowerCase().includes(q)).slice(0,6);$('#search-results').innerHTML=pages.map(([id,ic,l])=>`<button class="search-result" data-nav="${id}">${icon(ic)}${l}<small>PAGE</small></button>`).join('')+devices.map(d=>`<button class="search-result" data-device="${esc(d.id)}">${icon(deviceIcon(d.type))}${esc(d.name)}<small>${esc(d.ip)}</small></button>`).join('')+(!pages.length&&!devices.length?'<p class="subtitle" style="padding:14px">No matches found.</p>':'');}
async function sendChat(message){if(!requireAuth())return;if(state.chatBusy||!message.trim())return;const history=state.messages.filter(m=>!m.error).slice(-8).map(({role,content})=>({role,content:content.slice(0,8000)}));state.messages.push({role:'user',content:message});state.chatBusy=true;render();try{const result=await api('/chat',{message,history});state.messages.push({role:'assistant',content:result.message,provider:result.provider,actions:result.actions});await refresh(false);}catch(e){state.messages.push({role:'assistant',content:`${e.message}\n\nCheck the provider URL and installed model in Settings → AI & workspace. For an immediate telemetry summary without a model, choose “Local status only”.`,provider:'CONNECTION NOTICE',error:true});}finally{state.chatBusy=false;if(state.page==='assistant')render();}}
function modalError(id,error){const el=$(id);if(el)el.innerHTML=`<div class="inline-error" role="alert">${esc(error.message||error)}</div>`;else toast(error.message||error,true);}
async function handleAction(name,el){
  if(name==='workspace'){workspaceModal();return;}
  if(name==='pair-start'){await startPairing(el);return;}
  if(name==='workspace-integrations'){await navigate('settings','integrations');return;}
  if(name==='workspace-deployment'){await navigate('settings','deployment');return;}
  if(name==='security-details'){if(requireAuth())securityDetailsModal();return;}
  if(name==='security-settings'){await navigate('settings','security');return;}
  if(name==='network-identity'){await networkIdentityModal();return;}
  if(name==='detect-isp'){if(!requireAuth())return;el.disabled=true;const oldLabel=el.innerHTML;el.textContent='Detecting…';try{const identity=await api('/network-identity/detect',{allowExternal:true,forceRefresh:true,useDetected:true});if(identity.lookupInProgress)throw new Error('A lookup is already running. Try again shortly.');if(identity.isp?.status!=='detected')throw new Error(identity.isp?.message||'ISP lookup is unavailable. Your manual selection has been kept.');state.overview.networkIdentity=identity;await networkIdentityModal();toast(`Automatic provider: ${identity.isp.name}`);}catch(e){modalError('#identity-error',e);}finally{el.disabled=false;el.innerHTML=oldLabel;}return;}
  if(name==='close'){closeModal();return;}
  if(name==='menu'){state.sidebarOpen=!state.sidebarOpen;$('#sidebar')?.classList.toggle('open',state.sidebarOpen);return;}
  if(name==='auth'){authModal();return;}
  if(name==='add'){providerPicker();return;}
  if(name==='connect-ha'){connectionModal('homeassistant',integration('homeassistant')||{});return;}
  if(name==='connect-camera'){connectionModal('hikvision');return;}
  if(name==='help'){helpModal();return;}
  if(name==='search'){searchModal();return;}
  if(name==='ai-settings'){navigate('settings','ai');return;}
  if(name==='activity'){await refresh(false);activityModal();return;}
  if(name==='approvals'){await refresh(false);approvalsModal();return;}
  if(name==='account'){if(!requireAuth())return;navigate('settings','security');return;}
  if(name==='logout'){if(!state.status.authenticated)return;await api('/auth/logout',{});clearPrivateState();state.status=await api('/status');closeModal();render();toast('You’ve been signed out.');return;}
  if(name==='refresh'){if(!requireAuth())return;await refresh();toast('Live telemetry refreshed.');return;}
  if(name==='scan'){if(!requireAuth())return;const n=state.overview.network;openModal('Discover this network.','Start discovery only when you are connected to the network you want to inspect.',`<div class="info-row"><span>Interface</span><strong>${esc(n.interface||'Current interface')}</strong></div><div class="info-row"><span>Local address</span><strong>${esc(n.localAddress||'Not available')}</strong></div><p class="subtitle" style="line-height:1.9;margin-top:17px">Homebase reads the local neighbor table and sends an SSDP discovery request. It enables gateway latency sampling and refreshes discovery every 60 seconds. Discovery pauses and clears the inventory if this host changes networks. It won’t pair, change, or control devices.</p><div class="form-actions">${button('Cancel','close','','ghost')}${button('Scan current network','scan-confirm','scan','')}</div>`,{kind:'scan'});return;}
  if(name==='scan-confirm'){if(!requireAuth())return;closeModal();state.scanBusy=true;render();try{const data=await api('/discovery',{});await refresh(false);toast(`Discovery complete. ${data.devices?.length||0} devices found on the current network.`);}finally{state.scanBusy=false;render();}return;}
  if(name==='entities'){await loadEntities();return;}
  if(name==='servers'){await loadServers();return;}
  if(name==='entity-service'){const entity=el.dataset.entity,domain=entity.split('.')[0];await propose('ha.service',el.dataset.integration,{domain,service:['script','scene'].includes(domain)?'turn_on':domain==='media_player'?'media_play_pause':'toggle',entityId:entity});return;}
  if(name==='models'){if(!requireAuth())return;el.disabled=true;try{const data=await api('/ai/models');const models=data.models||[];const root=$('#model-results');if(root)root.innerHTML=models.length?`<label class="field"><span class="field-label">Available models</span><select id="available-models"><option value="">Select a model…</option>${models.map(m=>`<option value="${esc(m.id||m.name)}">${esc(m.name||m.id)}</option>`).join('')}</select></label>`:'<p class="subtitle">No installed models were reported by this provider.</p>';}finally{el.disabled=false;}return;}
  if(name==='mfa'){if(!requireAuth())return;const enrollment=await api('/auth/mfa/setup',{});openModal('Add a second layer.','In your authenticator app, add an account using this setup key. Then enter its current six-digit code.',`<p class="field-label">Setup key</p><pre class="code">${esc(enrollment.secret)}</pre><p class="subtitle">Type: time-based (TOTP) · 6 digits · 30-second interval</p><form id="mfa-form">${field('Authenticator code','code','','123456','text','','required inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6"')}<div id="mfa-error"></div><div class="form-actions">${button('Cancel','close','','ghost')}<button class="btn" type="submit">${icon('shield')}Enable two-factor</button></div></form><div class="note" style="margin-top:18px">Keep this key in a safe place. You will need your authenticator to sign in. There is no email recovery service.</div>`,{kind:'mfa'});return;}
}

document.addEventListener('click',async event=>{
  const el=event.target.closest('button,[data-action]');if(!el||el.disabled)return;
  try{
    if(el.dataset.nav){await navigate(el.dataset.nav);return;}
    if(el.dataset.settings){await navigate('settings',el.dataset.settings);return;}
    if(el.dataset.edit){const config=state.overview.integrations.find(i=>i.id===el.dataset.edit);if(config)connectionModal(config.type,config);return;}
    if(el.dataset.connect){connectionModal(el.dataset.connect);return;}
    if(el.dataset.range){state.graphRange=Number(el.dataset.range);$$('[data-range]').forEach(b=>b.classList.toggle('active',b===el));drawChart();return;}
    if(el.dataset.filter){state.deviceFilter=el.dataset.filter;render();return;}
    if(el.dataset.entityFilter){state.entityFilter=el.dataset.entityFilter;render();return;}
    if(el.dataset.prompt){await sendChat(el.dataset.prompt);return;}
    if(el.dataset.pairTv){const config=state.overview.integrations.find(i=>i.id===el.dataset.pairTv);if(config)pairingModal(config);return;}
    if(el.dataset.tvCandidate){const d=state.overview.devices.find(d=>d.id===el.dataset.tvCandidate);if(d)connectionModal(d.suggestedIntegration||'androidtv',{name:d.name,host:d.suggestedHost||d.ip,protocol:d.suggestedProtocol||d.protocol,connectionMode:'direct'});return;}
    if(el.dataset.cameraCandidate){const candidate=state.overview.devices.find(d=>d.id===el.dataset.cameraCandidate);if(candidate)connectionModal('hikvision',{name:candidate.name||'Discovered Hikvision camera',host:candidate.suggestedHost||candidate.host||('http://'+candidate.ip),channel:101});return;}
    if(el.dataset.device){const d=state.overview.devices.find(d=>d.id===el.dataset.device);if(d)openModal(esc(d.name),'Observed on the current local network.',`<div>${[['Address',d.ip],['MAC address',d.mac||'Not reported'],['Device type',d.type],['Vendor',d.vendor||'Not reported'],['Last seen',date(d.lastSeen)]].map(([k,v])=>`<div class="info-row"><span>${k}</span><strong>${esc(v||'—')}</strong></div>`).join('')}</div><div class="note" style="margin-top:19px">${icon('info')}Discovery does not pair this device. Add an authorized integration to enable supported controls.</div><div class="form-actions">${button('Connect integration','add','plus','secondary')}</div>`,{kind:'device'});return;}
    if(el.dataset.tv){const command=el.dataset.command;await propose('tv.command',el.dataset.tv,{command});return;}
    if(el.dataset.test){if(!requireAuth())return;el.disabled=true;try{const result=await api(`/integrations/${encodeURIComponent(el.dataset.test)}/test`,{});await refresh(false);render();toast(result.message||result.status,result.status==='error');}finally{el.disabled=false;}return;}
    if(el.dataset.delete){const i=state.overview.integrations.find(i=>i.id===el.dataset.delete);closeModal();openModal(TV_TYPES.includes(i?.type)?'Remove this TV?':'Remove this connection?',`Remove ${esc(i?.name||'this integration')} and its encrypted credentials from Homebase.`, `<p class="subtitle">This removes only the saved HomeBase connection and its encrypted credentials. It does not switch off or reset the device. A TV can still appear in network discovery; revoke HomeBase on the TV itself if you also want to remove its device-side authorization.</p><div class="form-actions">${button('Keep connection','close','','ghost')}<button class="btn danger" data-delete-confirm="${esc(el.dataset.delete)}">Remove connection</button></div>`,{kind:'delete'});return;}
    if(el.dataset.deleteConfirm){await api(`/integrations/${encodeURIComponent(el.dataset.deleteConfirm)}`,{},'DELETE');closeModal();await refresh(false);render();toast('Connection removed.');return;}
    if(el.dataset.approve||el.dataset.reject){const id=el.dataset.approve||el.dataset.reject;const approve=!!el.dataset.approve;el.disabled=true;el.textContent=approve?'Executing approved action…':'Rejecting…';const {action}=await api(`/actions/${encodeURIComponent(id)}/${approve?'approve':'reject'}`,{});await refresh(false);approvalsModal();toast(action.status==='failed'?action.error:approve?'Approved action completed.':'Action rejected.',action.status==='failed');return;}
    if(el.dataset.snapshot){if(!requireAuth())return;el.disabled=true;try{const response=await fetch(`/api/cameras/${encodeURIComponent(el.dataset.snapshot)}/snapshot`,{credentials:'same-origin'});if(!response.ok){const error=await response.json();throw new Error(error.message||'Snapshot unavailable.');}const blob=await response.blob();const url=URL.createObjectURL(blob);const root=document.getElementById('camera-'+el.dataset.snapshot);if(root){const old=state.cameraUrls[el.dataset.snapshot];if(old?.startsWith('blob:'))URL.revokeObjectURL(old);state.cameraUrls[el.dataset.snapshot]=url;root.innerHTML='';const image=new Image();image.alt='Authorized camera snapshot';image.src=url;root.append(image);}else URL.revokeObjectURL(url);}finally{el.disabled=false;}return;}
    if(el.dataset.action)await handleAction(el.dataset.action,el);
  }catch(e){toast(e.message,true);}
});
document.addEventListener('error',event=>{const image=event.target;if(image.tagName==='IMG'&&image.classList.contains('brand-logo-image')){image.hidden=true;const fallback=image.parentElement.querySelector('.brand-logo-fallback');if(fallback)fallback.hidden=false;}},true);
document.addEventListener('input',event=>{if(event.target.id==='global-search')searchResults(event.target.value);if(event.target.id==='device-search'){const input=event.target,position=input.selectionStart;state.deviceSearch=input.value;render();const next=$('#device-search');next?.focus();next?.setSelectionRange(position,position);}if(event.target.id==='chat-input'){event.target.style.height='auto';event.target.style.height=Math.min(event.target.scrollHeight,130)+'px';}});
document.addEventListener('change',event=>{if(event.target.id==='tv-connection-mode'){const direct=event.target.value==='direct';for(const [id,active] of [['tv-direct-fields',direct],['tv-ha-fields',!direct]]){const fields=$('#'+id);fields.hidden=!active;fields.disabled=!active;}const host=$('#integration-form [name="host"]');const label=host.closest('label').querySelector('.field-label');label.textContent=direct?'TV address':'Home Assistant URL';host.placeholder=direct?'192.168.1.50':'http://homeassistant.local:8123';}if(event.target.id==='tv-protocol')$('#tv-local-channel-note').hidden=!insecureTV(event.target.value);if(event.target.id==='isp-mode'){const manual=event.target.value==='manual';$('#manual-isp-field').hidden=!manual;$('#manual-isp-field input').disabled=!manual;$('#automatic-isp-description').hidden=manual;}if(event.target.name==='homeAssistantId'&&event.target.value){const gateway=state.overview.integrations.find(i=>i.id===event.target.value);const host=$('#integration-form [name="host"]');if(gateway&&host)host.value=gateway.host;}if(event.target.id==='available-models'&&event.target.value)$('[name="model"]').value=event.target.value;if(event.target.id==='ai-provider'){const url=$('[name="baseUrl"]');if(event.target.value==='ollama'&&!url.value.includes('11434'))url.value='http://127.0.0.1:11434';if(event.target.value==='openai-compatible'&&url.value.includes('11434'))url.value='';}});
document.addEventListener('submit',async event=>{
  const form=event.target;if(!['auth-form','integration-form','ai-settings-form','chat-form','mfa-form','network-identity-form','workspace-form','tv-pair-form'].includes(form.id))return;event.preventDefault();const values=Object.fromEntries(new FormData(form));const submit=$('button[type="submit"]',form);if(submit)submit.disabled=true;
  try{
    if(form.id==='tv-pair-form'){if(!requireAuth())return;const pairing=state.pairing;if(!pairing?.pairingId)throw new Error('Start pairing again.');await api(`/tvs/${encodeURIComponent(pairing.integrationId)}/pair/finish`,{pairingId:pairing.pairingId,code:(values.code||'').trim(),approved:true});state.pairing=null;await refresh(false);closeModal();render();toast('TV paired. Remote commands will ask for approval.');}
    if(form.id==='workspace-form'){if(!requireAuth())return;state.settings=await api('/settings',{workspaceName:values.workspaceName});closeModal();render();toast('Workspace name saved.');}
    if(form.id==='auth-form'){if(state.status.setupRequired&&values.password!==values.confirm)throw new Error('Your passwords don’t match.');state.status=await api(state.status.setupRequired?'/auth/setup':'/auth/login',values);state.settings=await api('/settings');await refresh(false);closeModal();render();toast('Welcome home. Your private command centre is ready.');}
    if(form.id==='integration-form'){if(!requireAuth())return;const result=await api('/integrations',{...values,type:form.dataset.type,...(form.dataset.id?{id:form.dataset.id}:{})});await refresh(false);closeModal();if(values.connectionMode==='direct'){state.page='devices';state.deviceFilter='tv';history.replaceState(null,'','#devices');render();pairingModal(result.integration);}else{render();toast('Connection saved. Choose Check connection when ready.');}}
    if(form.id==='ai-settings-form'){if(!requireAuth())return;const {workspace,...ai}=values;state.settings=await api('/settings',{ai,...(workspace?{workspace}:{})});render();toast('AI configuration saved securely.');}
    if(form.id==='mfa-form'){await api('/auth/mfa/confirm',values);state.settings=await api('/settings');closeModal();render();toast('Two-factor authentication is enabled.');}
    if(form.id==='chat-form'){await sendChat(values.message);}
    if(form.id==='network-identity-form'){if(!requireAuth())return;const manual=values.ispMode==='manual';if(manual&&!values.ispName?.trim())throw new Error('Enter an ISP name for Manual mode, or select Automatic.');const needsLookup=!manual&&(!!state.settings.networkIdentity?.ispName||!state.overview.networkIdentity?.isp?.name||state.overview.networkIdentity?.isp?.status==='unavailable');state.settings=await api('/settings',{networkIdentity:{ispName:manual?values.ispName.trim():'',routerName:values.routerName||'',allowExternalLookup:values.allowExternalLookup==='on'}});if(needsLookup){const detected=await api('/network-identity/detect',{allowExternal:true,forceRefresh:true,useDetected:true});state.overview.networkIdentity=detected;if(detected.lookupInProgress||detected.isp?.status!=='detected'){await networkIdentityModal();throw new Error(detected.isp?.message||'Automatic detection is still in progress. Please try again shortly.');}}await refresh(false);closeModal();render();toast(manual?'Manual provider and appearance saved.':'Automatic provider and appearance saved.');}
  }catch(e){modalError({'auth-form':'#auth-error','integration-form':'#integration-error','ai-settings-form':'#settings-error','mfa-form':'#mfa-error','network-identity-form':'#identity-error','workspace-form':'#workspace-error','tv-pair-form':'#pairing-error'}[form.id],e);}finally{if(submit)submit.disabled=false;}
});
document.addEventListener('keydown',event=>{
  if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();searchModal();return;}
  if(event.key==='Escape'){closeModal();state.sidebarOpen=false;$('#sidebar')?.classList.remove('open');}
  if(event.target.id==='chat-input'&&event.key==='Enter'&&!event.shiftKey){event.preventDefault();$('#chat-form')?.requestSubmit();}
  if(event.key==='Tab'&&state.modal){const focusable=$$('button:not([disabled]),input:not([disabled]),select,textarea,a[href]', $('.modal'));const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if([...NAV.map(n=>n[0]),'settings'].includes(page))navigate(page);});
async function boot(){try{state.status=await api('/status');if(state.status.authenticated){state.settings=await api('/settings');await refresh(false);}render();}catch(e){$('#app').innerHTML=`<div class="boot"><div class="boot-logo">H</div><h1>Homebase is starting up.</h1><p>${esc(e.message)}</p><p>Check the HomeBase service logs, then refresh this page.</p></div>`;}}
await boot();
let lastUserActivity=Date.now(),pollCount=0;
for(const eventName of ['pointerdown','keydown','touchstart'])document.addEventListener(eventName,()=>lastUserActivity=Date.now(),{passive:true});
setInterval(async()=>{if(state.status.authenticated&&Date.now()-lastUserActivity>30*60000){try{await api('/auth/logout',{});}catch{}clearPrivateState();render();toast('Your session was locked after 30 minutes without interaction.');return;}if(!document.hidden){await refresh();if(++pollCount%3===0&&state.serversLive&&state.page==='devices')loadServers();}},3000);
